import{_ as l,C as o,c as i,o as a,aa as p,G as c}from"./chunks/framework.Cn7WEiMX.js";const f=JSON.parse('{"title":"简单方块定义","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/mod-support/defining-a-simple-block.md","filePath":"wiki/Dynmap/mod-support/defining-a-simple-block.md"}'),n={name:"wiki/Dynmap/mod-support/defining-a-simple-block.md"};function s(r,e,m,h,u,g){const t=o("NolebaseGitContributors"),d=o("NolebaseGitChangelog");return a(),i("div",null,[e[0]||(e[0]=p(`<h1 id="简单方块定义" tabindex="-1">简单方块定义 <a class="header-anchor" href="#简单方块定义" aria-label="Permalink to &quot;简单方块定义&quot;">​</a></h1> <p>A simple block is a solid cubic block filling the whole cube where a block is placed. This is the most common kind of block, and is best used whenever possible (for both simplicity of implementation, and for performance). As the solid cubic block is the default model for a block, these blocks do not need corresponding definitions in the Model Definition Files. The block texture definition is defined via the &#39;block:&#39; directive.</p> <p>简单方块即为一般的完整方块。大部分方块属于简单方块，且建议尽可能使用它（使得实现简化及性能最佳目的）。完整方块为默认模型，无需在<a href="./model-definition-files">模型定义文件</a>中额外设置。方块纹理定义通过 <code>block</code> 属性完成。</p> <p>简单方块有六面，且拥有如下设置：</p> <ul><li><code>top</code>、<code>face1</code> 或 <code>patch4</code>（方块顶面）</li> <li><code>bottom</code>、<code>face0</code> 或 <code>patch1</code>（方块底面）</li> <li><code>north</code>、<code>face4</code> 或 <code>patch0</code>（X 轴负向位置——目前为西面；在 GA 前曾为北面）</li> <li><code>south</code>、<code>face5</code> 或 <code>patch3</code>（X 轴正向位置——目前为东面；在 GA 前曾为南面）</li> <li><code>west</code>、<code>face3</code> 或 <code>patch5</code>（Z 轴正向位置——目前为南面；在 GA 前曾为西面）</li> <li><code>east</code>、<code>face2</code> 或 <code>patch2</code>（Z 轴负向位置——目前为北面；在 GA 前曾为东面）</li></ul> <p>每面纹理由对应属性提供的纹理引用设置，且需要指定方块 ID 属性，即 <code>id</code>：</p> <div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>block:id=&lt;方块 ID&gt;,&lt;side&gt;=&lt;序号+函数&gt;:&lt;纹理 ID&gt;,&lt;side&gt;=&lt;序号+函数&gt;:&lt;纹理 ID&gt;,...</span></span></code></pre></div><p>普通多面组合还有便捷写法，允许同一纹理应用至方块的多个面：</p> <ul><li><code>allfaces</code>（全六面使用同一纹理）</li> <li><code>allsides</code>（全四侧面使用同一纹理）</li> <li><code>topbottom</code>（顶底面使用同一纹理）</li></ul> <p>因为旧版兼容性问题，普通的实心方块还需要指定 <code>stdrot=true</code> 设置。这会修正顶底面的旋转——否则这些纹理会与游戏实机表现额外旋转 90 度。</p> <p>若若要同一纹理映射应用到所有元数据值，请指定 <code>data=*</code> 属性（尽管这是 <code>data</code> 参数的默认设置）。若只指定某个元数据状态使用特定的纹理映射，那么必须设置一或多个 <code>data=&lt;数字&gt;</code> 属性。</p> <p>若一或多个方块 ID 用到了同一组纹理映射，可以在同一个 <code>block</code> 设置下添加额外的 <code>id</code> 属性。</p> <p>这里还有几个可以指定的其他属性：</p> <ul><li><code>txtid</code> - 如上所述，允许在 <code>block</code> 定义中，为没有 <code>:</code> 跟随后缀的定义指定默认的纹理 ID。</li> <li><code>transparency</code> - 影响方块光照的计算方式。若为 <code>opaque</code>（默认值），则方块表面光照基于邻近方块处理。若为 <code>transparent</code>，方块表面光照基于自身光照等级处理。若为 <code>semitransparent</code>，方块光照则为二者的特殊结合（适用于不完整方块——如台阶和楼梯）。若为 <code>leaves</code>，则取决于树叶处理的方式（与 <code>transparent</code> 大致相同，部分 Spout 版本上的 Dynmap 略有区别）。</li> <li><code>colorMult</code> - 影响所有使用了 <code>multiplier-tinting</code> 选项（17000，21000）的纹理，包含六位十六进制值：RRGGBB，RR 为红通道值（00-FF），GG 为绿通道值，BB 则为蓝通道值。</li> <li><code>customColorMult</code> - 影响所有使用了 <code>multiplier-tinting</code> 选项（17000，21000）的纹理，包含染色类的完整类名。目前定义值包含如下：
<ul><li><code>org.dynmap.hdmap.colormult.TFBandedWoodColorMultiplier</code> - 暮色森林条纹木特殊着色功能</li> <li><code>org.dynmap.hdmap.colormult.TFMagicLeafColorMultiplier</code> - 暮色森林魔力树树叶特殊着色功能</li> <li><code>org.dynmap.hdmap.colormult.TFSpecialLeafColorMultiplier</code> - 暮色森林特殊树叶着色功能</li></ul></li> <li><code>layer&lt;M&gt;</code> 或 <code>layer&lt;M&gt;-&lt;N&gt;</code> 允许纹理“堆叠”——若某侧纹理透明，则下一层纹理会叠加在透明一侧。<code>layer&lt;M&gt;</code> 或 <code>layer&lt;M&gt;-&lt;N&gt;</code> 属性的值为下一层背后的纹理对应 <code>patch&lt;序号&gt;</code> 或 <code>patch&lt;M&gt;</code> 到 <code>patch&lt;N&gt;</code> 之间所有补丁的定义。对于标准方块，标准侧面使用的是 patch0 至 5，因此任意额外层纹理都从 patch6 起算。</li> <li><code>patch&lt;M&gt;</code> 或 <code>patch&lt;M&gt;-&lt;N&gt;</code> - 这些属性允许定义除默认六面纹理（patch0 至 patch5，或上述等价于其他关键词的属性）外的引用。对于标准方块，这些只用于定义多层纹理。设置的值为纹理引用，应用至第 M 补丁，或所有 M 与 N 之间的对应补丁。</li></ul> `,27)),c(t),c(d)])}const k=l(n,[["render",s]]);export{f as __pageData,k as default};
